# events

实现 src/reconcile.mjs 导出的 reconcile，保持 src/caller.mjs 兼容。

reconcile(current, events)纯函数返回按id的JavaScript字符串比较排序的记录数组。current为唯一id记录，形态{id,version,deleted,value?}；events为按到达顺序的{id,version,type:'upsert'|'delete',value?}。id为任意非空字符串，version为非负安全整数，deleted为布尔。upsert及非删除记录必须有自有value属性，value可为任意JSON值。两参数均为稠密数组；任何非法项或current重复id使整个调用抛TypeError，不修改任何输入。每个id仅接受比已知version更大的事件；相同版本先存在/先到达者胜出。删除保留{id,version,deleted:true}墓碑以挡住较旧更新；upsert产生{id,version,deleted:false,value}。输出记录只含这些字段，不修改或排序输入；再次应用相同事件须幂等。

只允许修改 src/reconcile.mjs 和新增 test/extra.test.mjs；其余公开文件不可修改。无依赖安装、外部服务或数据库影响。公共验证：node --test test/public.test.mjs；新增自测后也要实际运行。

export function reconcile(current, events) { const records = Object.fromEntries(current.map(row => [row.id,row])); for (const e of events) { if (e.type === "delete") delete records[e.id]; else records[e.id] = {id:e.id,version:e.version,deleted:false,value:e.value}; } return Object.values(records); }

import { reconcile } from "./reconcile.mjs";
export function sync(snapshot, events) { const records = reconcile(snapshot, events); return { records, visible: records.filter(row => !row.deleted) }; }

